def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Uniform rows and columns mark the lines to recolor.
    marked_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    marked_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    for r in marked_rows:
        for c in range(w):
            out[r][c] = 2
    for c in marked_cols:
        for r in range(h):
            out[r][c] = 2
    return out
